    ARRAY[$s$draft a consent form$s$, $s$session recording consent statement$s$, $s$testimonial release wording$s$, $s$data collection disclosure for clients$s$, $s$I need a consent and disclosure statement$s$, $s$permission wording for using a client testimonial$s$]::text[],
    $j$[{"id": "gather_consent_context", "tool": "context", "desc": "Read the tenant's declared business type, brand voice, region, and the specific consent purpose being requested (recording, data collection, testimonial use) from tenant/brand context. Use only present specifics; ask the tenant for the exact scope of consent rather than inventing it (§15)."}, {"id": "gather_disclosure_structure", "tool": "rag", "desc": "Retrieve the generic structural elements a plain-language consent/disclosure statement typically covers (what is being consented to, purpose, how the information/recording is used and stored, how consent can be withdrawn, contact) as neutral scaffolding — no jurisdiction-specific legal conclusions."}, {"id": "generate_consent_with_disclaimer", "tool": "anthropic", "desc": "Generate the consent/disclosure draft in the tenant's voice (§3), and PREPEND an explicit in-copy disclaimer block: this is a generic starting template and general information, NOT legal, tax, or regulatory advice; Paige is not a lawyer and gives no legal determination; the tenant must have it reviewed by a qualified attorney for their jurisdiction before using it with clients. Coaching-generic only, phrased positively, zero prohibited-vertical wording (§2)."}, {"id": "file_draft_for_approval", "tool": "client_memory", "desc": "File the drafted consent/disclosure statement as a DRAFT for the tenant's review and approval (autonomy_lane=confirm) — never sent to a client, never certified. A human approves before any use."}, {"id": "render_draft_document", "tool": "pdf_render", "desc": "Render the approved-pending draft (disclaimer block included) as a shareable document the tenant can hand to their attorney for review."}]$j$::jsonb,
