    $j$[{"id": "gather_profile", "tool": "context", "desc": "Load the tenant's declared business type, jurisdiction/region, and the nature of the deal or relationship the contract governs from the tenant profile and prior context; use only fields that are actually present and never invent a jurisdiction, party, or term."}, {"id": "gather_considerations", "tool": "rag", "desc": "Retrieve coaching-generic contract-review considerations (scope of work, term and termination, payment and cancellation terms, ownership of deliverables, confidentiality, limitation of liability, auto-renewal, dispute resolution) relevant to the tenant's declared business and region from the knowledge base."}, {"id": "generate_checklist", "tool": "anthropic", "desc": "Generate a plain-language pre-signing REVIEW checklist of what to look for and what questions to raise, in the tenant's voice, and embed an explicit disclaimer at the top and bottom that this is a general starting template and general information ONLY, is NOT legal, tax, or regulatory advice, that Paige is not a lawyer and makes no legal determination, and that the tenant must have a qualified attorney review it for their jurisdiction before relying on it or signing."}, {"id": "persist_draft", "tool": "client_memory", "desc": "Persist the checklist as a DRAFT filed for the tenant's approval; the skill never treats it as final, never signs, and never acts on the contract."}, {"id": "render_pdf", "tool": "pdf_render", "desc": "Render the pending-approval checklist as a downloadable document for the tenant to review and take to their attorney."}]$j$::jsonb,
