    $j$[{"id": "gather_profile", "tool": "context", "desc": "Load the tenant's declared business type, region, and any known data-collection touchpoints (intake forms, scheduling, payments handled by their own processor, communications) from the tenant profile and prior context; use only present fields and never fabricate a system, vendor, or practice the tenant has not declared."}, {"id": "gather_practices", "tool": "rag", "desc": "Retrieve coaching-generic data-governance considerations (categories of data collected, storage location, access control, retention period, protection measures, disposal, consent and opt-out) relevant to the tenant's declared business and region from the knowledge base."}, {"id": "research_references", "tool": "firecrawl", "desc": "Optionally gather general, publicly available best-practice references on plain-language data-handling summaries for small service businesses in the tenant's region; treat these as general information to inform structure only, never as an authoritative or jurisdiction-specific legal source."}, {"id": "generate_summary", "tool": "anthropic", "desc": "Generate a plain-language data-handling summary in the tenant's voice describing what data is collected, where it is stored, who accesses it, how long it is kept, and how it is protected and disposed of — using only tenant-declared facts and marking anything unknown as 'not specified' rather than guessing — and embed an explicit disclaimer that this is a general starting template and general information ONLY, is NOT legal, tax, or regulatory advice, makes no compliance determination, and must be reviewed by a qualified attorney or privacy professional for the tenant's jurisdiction before use."}, {"id": "persist_draft", "tool": "client_memory", "desc": "Persist the summary as a DRAFT filed for the tenant's approval; the skill never publishes it, never files it with any authority, and never asserts a compliance status."}, {"id": "render_pdf", "tool": "pdf_render", "desc": "Render the pending-approval summary as a downloadable document for the tenant to review with a professional."}]$j$::jsonb,
